// Writes js/contributions.js: the pull requests jonbttt has opened on other
// people's public repositories that are merged or still open. Closed-unmerged
// ones are left out. Run daily by .github/workflows/contributions.yml.
//
// It is written as a script that sets a global, not JSON, so the site still
// reads it when opened straight from disk, where fetch() is refused.

import { writeFile } from 'node:fs/promises';

const USER = 'jonbttt';
const OUT = 'js/contributions.js';

const headers = { Accept: 'application/vnd.github+json', 'User-Agent': USER };
if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;

async function get(url) {
  const res = await fetch(url, { headers });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}: ${url}`);
  return res.json();
}

const q = encodeURIComponent(`type:pr author:${USER} -user:${USER} is:public`);
const { items } = await get(`https://api.github.com/search/issues?q=${q}&sort=created&order=desc&per_page=100`);

const list = items
  .filter((pr) => pr.state === 'open' || pr.pull_request?.merged_at)
  .map((pr) => ({
    repo: pr.repository_url.replace('https://api.github.com/repos/', ''),
    title: pr.title.trim(),
    number: pr.number,
    url: pr.html_url,
    status: pr.state === 'open' ? 'open' : 'merged',
    date: (pr.pull_request.merged_at || pr.created_at).slice(0, 10),
  }))
  // merged work first, newest first within each
  .sort((a, b) => (a.status === b.status ? b.date.localeCompare(a.date) : a.status === 'merged' ? -1 : 1));

const body = list.map((c) => '  ' + JSON.stringify(c)).join(',\n');
await writeFile(OUT,
  '/* Generated by .github/scripts/contributions.mjs, run daily by\n' +
  '   .github/workflows/contributions.yml. Edits here are overwritten. */\n' +
  `window.CONTRIBUTIONS = [\n${body}${body ? '\n' : ''}];\n`);
console.log(`${list.length} contributions written to ${OUT}`);
